' "ShrtCaseSensitive":true,',
' "OnSearchShowChildren":true,',
' "UseFocus":true,',
' "Shortcuts" : []',
'}'))
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'{',
'  "MenuOpen": false,',
'  "MenuClickOpenClose": true,',
'  "SaveSS": true,',
'  "ShortcutSaveSS": false,',
'  "ShrtCaseSensitive": true,',
'  "OnSearchShowChildren": true,',
'  "UseFocus": true,',
'  "Shortcuts": [',
'    {',
'      "name": "home",',
'      "action": "page",',
'      "page_id": 1,',
'      "clearCache": true,',
'      "clearCacheList": "1,300"',
'    },',
'    {',
'      "name": "n$emp",',
'      "action": "page",',
'      "page_id": 300,',
'      "newWindow": true,',
'      "clearCache": true,',
'      "clearCacheList": "RIR,300"',
'    },',
