'    {',
'      "name": "person",',
'      "action": "IR",',
'      "IR_type": "column",',
'      "IR_column": "ENAME",',
'      "IR_value": "KING",',
'      "IR_operator": "C",',
'      "IR_clearCache": "RIR",',
'      "page_id": 300,',
'      "example": "person:andrej"',
'    },',
'    {',
'      "name": "king",',
'      "action": "IR",',
'      "IR_type": "column",',
'      "IR_column": "ENAME",',
'      "IR_value": "KING",',
'      "IR_operator": "EQ",',
'      "IR_clearCache": "RIR",',
'      "page_id": 300',
'    },',
'    {',
'      "name": "job",',
'      "action": "IR",',
'      "IR_type": "column",',
'      "IR_column": "JOB",',
'      "IR_operator": "EQ",',
'      "IR_clearCache": "RIR",',
'      "page_id": 300,',
'      "example": "job:MANAGER"',
'    },',
